#!/usr/bin/env bash
set -e
echo "Pakker ut ERA Talents-appen..."
cat << 'EOF_B64' | base64 -d > /tmp/era-talents-app.tar.gz

EOF_B64
tar xzf /tmp/era-talents-app.tar.gz
rm /tmp/era-talents-app.tar.gz
echo "Filer pakket ut. Installerer avhengigheter (npm install)..."
npm install
echo ""
echo "================================================================"
echo "FERDIG. Gjenstaar foer appen kan kjoere:"
echo "1. Lag filen .env.local med disse tre linjene:"
echo ""
echo "   BRAWL_STARS_API_KEY=din-brawl-stars-token"
echo "   SUPABASE_URL=https://xxxxx.supabase.co"
echo "   SUPABASE_SERVICE_ROLE_KEY=din-supabase-service-role-nokkel"
echo ""
echo "2. Kjoer SQL-en i supabase/schema.sql i Supabase sitt SQL Editor"
echo "   (hvis du ikke allerede har gjort det)"
echo ""
echo "3. Start appen: npm run dev"
echo "================================================================"